#!/usr/bin/env bash
# Vendors the generated Fanous theme registry from the monorepo at the commit pinned in fanous.lock.
#   scripts/sync-fanous.sh            write the files
#   scripts/sync-fanous.sh --check    fail if the vendored files differ from the pinned commit (CI)
# The registry is generated by packages/fanous-tokens (`pnpm tokens:generate`); never edit it here.
set -euo pipefail
cd "$(dirname "$0")/.."
read -r REPO SHA < fanous.lock
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
git -c advice.detachedHead=false clone -q --filter=blob:none --no-checkout "https://github.com/$REPO.git" "$WORK/src"
git -C "$WORK/src" sparse-checkout set --no-cone /packages/fanous-tokens/generated/native/swift /packages/fanous-tokens/generated/native/svg
git -C "$WORK/src" checkout -q "$SHA"
NATIVE="$WORK/src/packages/fanous-tokens/generated/native"

OUT="$WORK/out"
SOURCES="$OUT/Packages/AUNDesign/Sources/AUNDesign"
mkdir -p "$SOURCES/Generated" "$SOURCES/Resources/Fanous.xcassets"
cp "$NATIVE/swift/FanousThemes.swift" "$SOURCES/Generated/FanousThemes.swift"
printf '{"info":{"author":"xcode","version":1}}\n' > "$SOURCES/Resources/Fanous.xcassets/Contents.json"
for svg in "$NATIVE"/svg/*/*/*.svg; do
  mode=$(basename "$(dirname "$svg")"); theme=$(basename "$(dirname "$(dirname "$svg")")"); name=$(basename "$svg" .svg)
  set="$SOURCES/Resources/Fanous.xcassets/fanous-$theme-$name-$mode.imageset"
  mkdir -p "$set"
  cp "$svg" "$set/$name.svg"
  printf '{"images":[{"filename":"%s.svg","idiom":"universal"}],"info":{"author":"xcode","version":1},"properties":{"preserves-vector-representation":true}}\n' "$name" > "$set/Contents.json"
done

TARGETS=(Packages/AUNDesign/Sources/AUNDesign/Generated Packages/AUNDesign/Sources/AUNDesign/Resources/Fanous.xcassets)
if [[ "${1:-}" == "--check" ]]; then
  for t in "${TARGETS[@]}"; do
    if ! diff -r "$OUT/$t" "$t" >/dev/null; then
      diff -r "$OUT/$t" "$t" | head -20
      echo "::error::$t is not the registry at $REPO@$SHA. Run scripts/sync-fanous.sh."
      exit 1
    fi
  done
  echo "Fanous registry matches $REPO@$SHA."
else
  for t in "${TARGETS[@]}"; do rm -rf "$t"; mkdir -p "$(dirname "$t")"; cp -R "$OUT/$t" "$t"; done
  echo "Vendored the Fanous registry from $REPO@$SHA."
fi
